import { Combobox, type ComboboxChangeDetail } from '@absoluteui/components/combobox';

const host = document.createElement('div');
document.body.append(host);
const country = Combobox.create(host, {
  label: 'Country',
  name: 'country',
  options: [
    { value: 'in', label: 'India' },
    { value: 'jp', label: 'Japan' },
    { value: 'de', label: 'Germany' },
  ],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<ComboboxChangeDetail>).detail;
  country.update({ invalid: value === null });
});

import { Combobox } from '@absoluteui/components/combobox';

